{
"html": "<div data-ui-unit="E5a" class="e5a-wrapper">
    <div class="e5a-content">
        <div class="e5a-header">
            <div class="e5a-profile">
                <img class="e5a-avatar" src="assets/icons/avatar-placeholder.png" alt="프로필 이미지">
                <div class="e5a-meta">
                    <span class="e5a-name">김민지</span>
                    <span class="e5a-role">프로덕트 디자이너</span>
                </div>
            </div>
            <button class="e5a-fav-btn" disabled aria-label="즐겨찾기">
                <img src="assets/icons/favorite-outline.png" alt="즐겨찾기">
            </button>
        </div>
        <p class="e5a-desc">사용자의 문제를 함께 정리하고 포트폴리오의 방향을 제안합니다.</p>
        <footer class="e5a-footer">
            <span class="e5a-price">예시 39,000원 / 회</span>
            <button class="e5a-cta-btn" disabled aria-label="상담 신청">
                상담
            </button>
        </footer>
    </div>
</div>",
"css": ".e5a-wrapper {
    width: 100%;
    display: flex;
    justify-content: center;
}

.e5a-content {
    background: var(--surface, #fff);
    border-radius: 14px;
    padding: 16px;
    min-width: 0;
    width: 100%;
    display: flex;
    flex-direction: column;
}

.e5a-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 8px;
}

.e5a-profile {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
}

.e5a-avatar {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    object-fit: cover;
    flex-shrink: 0;
}

.e5a-meta {
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-width: 0;
}

.e5a-name {
    font-weight: 700;
    font-size: 16px;
    color: var(--ink, #283548);
    line-height: 1.3;
}

.e5a-role {
    font-weight: 500;
    font-size: 14px;
    color: var(--muted, #566273);
    line-height: 1.4;
}

.e5a-fav-btn {
    background: none;
    border: none;
    padding: 4px;
    cursor: pointer;
    opacity: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}

.e5a-fav-btn img {
    width: 24px;
    height: 24px;
    display: block;
}

.e5a-desc {
    margin: 0 0 16px 0;
    font-size: 14px;
    line-height: 1.57;
    color: var(--muted, #566273);
    min-width: 0;
}

.e5a-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    flex-wrap: wrap;
}

.e5a-price {
    font-size: 14px;
    font-weight: 500;
    color: var(--ink, #283548);
    white-space: nowrap;
}

.e5a-cta-btn {
    background-color: rgba(54, 91, 204, 0.08);
    border: none;
    border-radius: 6px;
    padding: 6px 12px;
    font-size: 13px;
    font-weight: 700;
    color: var(--blue, #365bcc);
    cursor: pointer;
    white-space: nowrap;
    flex-shrink: 0;
}

@media (max-width: 320px) {
    .e5a-content {
        padding: 14px;
    }
    .e5a-footer {
        flex-direction: column;
        align-items: flex-start;
        gap: 8px;
    }
    .e5a-cta-btn {
        width: 100%;
        text-align: center;
    }
}"
}
